const parseIntEnv = (value: string | undefined, fallback: number): number => {
  const n = Number(value);
  return Number.isFinite(n) && n >= 0 ? Math.floor(n) : fallback;
};

export const SCYK_IMAGE_PURPOSE = 'medical-incident-attachment';
export const SCYK_IMAGE_PRODUCT = 'medical-incidents';
export const SCYK_IMAGE_ENTITY_TYPE = 'medical-incident';
export const SCYK_IMAGE_ACCEPT = 'image/jpeg,image/png,.jpg,.jpeg,.png';

const maxMb = Math.max(1, parseIntEnv(import.meta.env.VITE_SCYK_IMAGE_MAX_MB as string | undefined, 30));
/** 0 = optional on Gửi báo cáo (HDSD: Tài Liệu nếu có ảnh). */
const minFiles = parseIntEnv(import.meta.env.VITE_SCYK_IMAGE_MIN as string | undefined, 0);

export const scykImageUploadConfig = {
  minFiles,
  maxFiles: parseIntEnv(import.meta.env.VITE_SCYK_IMAGE_MAX as string | undefined, 10),
  maxMb,
  maxBytes: maxMb * 1024 * 1024,
  accept: SCYK_IMAGE_ACCEPT,
  purpose: SCYK_IMAGE_PURPOSE,
  product: SCYK_IMAGE_PRODUCT,
  entityType: SCYK_IMAGE_ENTITY_TYPE,
} as const;

